"""Synthetic wholesale banking book. SYNTHETIC BY DESIGN (case-study rule): generated by code, seeded and reproducible.

Counterparty names are public companies used as hypothetical borrowers; ratings, notionals and trade terms are random
draws, NOT real exposures. Pricing uses today's real curve, spreads, FX, oil and equity levels.
"""
from __future__ import annotations

import csv
from datetime import date, timedelta
from pathlib import Path

import numpy as np

from .pricing import IG_RATINGS, MarketState, spread_pct, value, years_to

# (name, ticker, sector, country ISO2)
COUNTERPARTIES = [
    ("JPMorgan Chase", "JPM", "Financials", "US"), ("Goldman Sachs", "GS", "Financials", "US"),
    ("Exxon Mobil", "XOM", "Energy", "US"), ("Chevron", "CVX", "Energy", "US"), ("Boeing", "BA", "Industrials", "US"),
    ("Caterpillar", "CAT", "Industrials", "US"), ("Apple", "AAPL", "Information Technology", "US"),
    ("Microsoft", "MSFT", "Information Technology", "US"), ("NVIDIA", "NVDA", "Information Technology", "US"),
    ("Alphabet", "GOOGL", "Communication Services", "US"), ("Amazon", "AMZN", "Consumer Discretionary", "US"),
    ("Walmart", "WMT", "Consumer Staples", "US"), ("Johnson & Johnson", "JNJ", "Health Care", "US"),
    ("UnitedHealth Group", "UNH", "Health Care", "US"), ("NextEra Energy", "NEE", "Utilities", "US"),
    ("Ford Motor", "F", "Consumer Discretionary", "US"), ("General Motors", "GM", "Consumer Discretionary", "US"),
    ("Tesla", "TSLA", "Consumer Discretionary", "US"), ("Verizon", "VZ", "Communication Services", "US"),
    ("AT&T", "T", "Communication Services", "US"), ("Pfizer", "PFE", "Health Care", "US"),
    ("Bank of America", "BAC", "Financials", "US"), ("Citigroup", "C", "Financials", "US"),
    ("Delta Air Lines", "DAL", "Industrials", "US"), ("Union Pacific", "UNP", "Industrials", "US"),
    ("Dow Inc", "DOW", "Materials", "US"), ("Freeport-McMoRan", "FCX", "Materials", "US"),
    ("Duke Energy", "DUK", "Utilities", "US"), ("Simon Property Group", "SPG", "Real Estate", "US"),
    ("Shell", None, "Energy", "GB"), ("BP", None, "Energy", "GB"), ("HSBC", None, "Financials", "GB"),
    ("Barclays", None, "Financials", "GB"), ("Unilever", None, "Consumer Staples", "GB"),
    ("Siemens", None, "Industrials", "DE"), ("Volkswagen", None, "Consumer Discretionary", "DE"),
    ("BASF", None, "Materials", "DE"), ("TotalEnergies", None, "Energy", "FR"), ("BNP Paribas", None, "Financials", "FR"),
    ("Toyota", None, "Consumer Discretionary", "JP"), ("Sony", None, "Consumer Discretionary", "JP"),
    ("Reliance Industries", None, "Energy", "IN"), ("Tata Steel", None, "Materials", "IN"),
    ("HDFC Bank", None, "Financials", "IN"), ("Infosys", None, "Information Technology", "IN"),
    ("Petrobras", None, "Energy", "BR"), ("Vale", None, "Materials", "BR"), ("America Movil", None, "Communication Services", "MX"),
    ("BHP", None, "Materials", "AU"), ("Samsung Electronics", None, "Information Technology", "KR"),
    ("Saudi Aramco", None, "Energy", "SA"), ("Alibaba", None, "Consumer Discretionary", "CN"),
]
SECTOR_RATINGS = {"Financials": ["A", "A", "BBB", "BBB"], "Utilities": ["BBB", "BBB", "BB"], "Energy": ["A", "BBB", "BBB", "BB"],
                  "Information Technology": ["AA", "A", "A", "BBB"], "Health Care": ["AA", "A", "BBB"],
                  "Consumer Staples": ["A", "BBB", "BBB"], "Communication Services": ["A", "BBB", "BB"],
                  "Consumer Discretionary": ["BBB", "BB", "BB", "B"], "Industrials": ["A", "BBB", "BBB", "BB"],
                  "Materials": ["BBB", "BB", "BB", "B"], "Real Estate": ["BBB", "BB", "B"]}
SECTOR_BETA_DEFAULT = 1.0


def _maturity(asof: date, years: float) -> date:
    return asof + timedelta(days=int(years * 365.25))


def generate_book(st: MarketState, sector_betas: dict | None = None, seed: int = 2026) -> list:
    rng = np.random.default_rng(seed)
    betas = sector_betas or {}
    book = []

    def add(kind, cp, rating, notional, maturity, terms, idx):
        name, tk, sector, country = cp
        book.append({"id": f"{kind[:1]}{idx:03d}", "asset_type": kind, "counterparty": name, "ticker": tk, "sector": sector,
                     "country": country, "notional": float(round(notional, -5)), "rating": rating, "maturity": maturity,
                     "terms": terms})

    idx = 0
    for cp in COUNTERPARTIES:                                            # one loan per counterparty
        idx += 1
        rating = str(rng.choice(SECTOR_RATINGS[cp[2]]))
        yrs = float(rng.uniform(1.5, 7.0))
        dm = spread_pct(rating, st)
        add("Loan", cp, rating, rng.uniform(25e6, 300e6), _maturity(st.asof, yrs),
            {"margin": round(dm + float(rng.normal(0, 0.30)), 3), "floating": True}, idx)
    for cp in rng.permutation(len(COUNTERPARTIES))[:32]:                 # bonds on a random subset
        cp = COUNTERPARTIES[int(cp)]
        idx += 1
        rating = str(rng.choice(SECTOR_RATINGS[cp[2]]))
        yrs = float(rng.uniform(2.0, 15.0))
        y_now = st.y(yrs) + spread_pct(rating, st)
        add("Bond", cp, rating, rng.uniform(10e6, 150e6), _maturity(st.asof, yrs),
            {"coupon": round(float(y_now + rng.normal(0, 0.5)) * 8) / 8}, idx)
    for k in range(10):                                                  # interest-rate swaps (pay fixed)
        cp = COUNTERPARTIES[int(rng.integers(0, len(COUNTERPARTIES)))]
        idx += 1
        yrs = float(rng.uniform(2.0, 10.0))
        add("Derivative", cp, "A", rng.uniform(50e6, 500e6), _maturity(st.asof, yrs),
            {"instrument": "irs_pay_fixed", "fixed": round(st.y(yrs) + float(rng.normal(0, 0.4)), 3)}, idx)
    for k in range(6):                                                   # FX forwards (long EUR / GBP vs USD)
        cp = COUNTERPARTIES[int(rng.integers(0, len(COUNTERPARTIES)))]
        idx += 1
        cur = "EUR" if k % 2 == 0 else "GBP"
        spot = st.eurusd if cur == "EUR" else st.gbpusd
        add("Derivative", cp, "A", rng.uniform(20e6, 200e6), _maturity(st.asof, float(rng.uniform(0.25, 1.0))),
            {"instrument": "fx_forward", "currency": cur, "strike": round(spot * (1 + float(rng.normal(0, 0.03))), 5)}, idx)
    for k in range(6):                                                   # equity total-return swaps (long)
        cp = COUNTERPARTIES[int(rng.integers(0, len(COUNTERPARTIES)))]
        idx += 1
        add("Derivative", cp, "A", rng.uniform(20e6, 150e6), _maturity(st.asof, float(rng.uniform(0.5, 3.0))),
            {"instrument": "equity_trs", "beta": round(float(betas.get(cp[2], SECTOR_BETA_DEFAULT)), 3),
             "strike": round(st.spx * (1 + float(rng.normal(0, 0.08))), 4)}, idx)
    for k in range(3):                                                   # commodity (oil) swaps (long)
        cp = COUNTERPARTIES[int(rng.integers(0, len(COUNTERPARTIES)))]
        idx += 1
        add("Derivative", cp, "A", rng.uniform(20e6, 120e6), _maturity(st.asof, float(rng.uniform(0.5, 2.0))),
            {"instrument": "commodity_swap", "strike": round(st.oil * (1 + float(rng.normal(0, 0.15))), 3)}, idx)
    return book


def holding_api(h: dict, st: MarketState) -> dict:
    return {"id": h["id"], "assetType": h["asset_type"], "counterparty": h["counterparty"], "sector": h["sector"],
            "country": h["country"], "notional": h["notional"], "marketValue": round(value(h, st), 2),
            "rating": h["rating"], "maturity": h["maturity"].isoformat()}


def write_csv(book: list, st: MarketState, path: str) -> None:
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(["id", "assetType", "counterparty", "ticker", "sector", "country", "notional", "marketValue", "rating", "maturity", "terms"])
        for h in book:
            w.writerow([h["id"], h["asset_type"], h["counterparty"], h["ticker"] or "", h["sector"], h["country"],
                        h["notional"], round(value(h, st), 2), h["rating"], h["maturity"].isoformat(), h["terms"]])
